"""Matched resource quotes, financing sensitivity and distinct housing calls; no tariffs or sources adopted."""
from decimal import Decimal as Q
q=lambda x:Q(str(x))
def compute(cfg,physical,pinputs,housing,hinputs,service125,pb):
 f=physical['food'];w=physical['water'];p=physical['power'];old=physical['prices'];rate=q(cfg['finance']['new_capital_interest']);capital={'food':q(f['all_new_asset_quote_CU']),'water':q(w['new_water_construction_CU']),'power':q(p['new_power_construction_CU'])};interest={k:v*rate for k,v in capital.items()}
 # Provided44people/parts remain in G. Reprice secondary sewage credit with the same changed power price.
 pp=(q(old['power_revenue_need_after_existing_G_support_CU'])+interest['power'])/(q(p['end_use_GWh'])*1000000)
 wc=q(old['water_resource_cost_CU'])+q(w['normal_electricity_GWh'])*1000000*(pp-q(old['power_exVAT_CU_kWh']))+interest['water'];wp=(wc-q(2140000)-q(p['secondary_public_overlap_matched_GWh'])*1000000*pp)/q(w['customer_m3'])
 fc=q(old['food_chain_cost_CU'])+q(f['electricity_GWh'])*1000000*(pp-q(old['power_exVAT_CU_kWh']))+q(f['farm_customer_m3'])*(wp-q(old['water_exVAT_CU_m3']))+interest['food'];shared=fc-q(f['normal_import_FU'])*q(pinputs['CU_per_FU']);mass=sum(q(v['received_units'])*(q(pinputs['food']['liquid_kg_litre_transport_only']) if v['unit']=='litre' else 1) for v in f['products']);products={}
 for r in f['products']:
  unitmass=q(pinputs['food']['liquid_kg_litre_transport_only']) if r['unit']=='litre' else Q(1);cost=q(r['annual_import_FU'])*q(pinputs['CU_per_FU'])+shared*q(r['received_units'])*unitmass/mass;price=cost/q(r['received_units']);products[r['id']]={'unit':r['unit'],'cost_allocation_exVAT_CU_unit':price,'private_exVAT_invoice_CU':price*q(r['private_received_units']),'public_exVAT_invoice_CU':price*q(r['public_received_units']),'private_consumer_VAT_sensitivity_CU':price*q(r['private_received_units'])*(1+q(cfg['food_VAT_sensitivity_by_product'][r['id']])),'public_VAT_sensitivity_CU':price*q(r['public_received_units'])*q(cfg['food_VAT_sensitivity_by_product'][r['id']])*(1-q(cfg['public_input_credit_fraction_hypothesis'])),'actual_market_price_or_VAT':None}
 publicfood=sum(v['public_exVAT_invoice_CU'] for v in products.values());privatefood=sum(v['private_exVAT_invoice_CU'] for v in products.values());bills={'public_electricity_CU':q(60000000)*pp*(1+q('.1')*(1-q(cfg['public_input_credit_fraction_hypothesis']))),'public_water_CU':q(1200000)*wp,'public_ingredients_exVAT_CU':publicfood,'public_ingredients_payable_sensitivity_CU':publicfood+sum(v['public_VAT_sensitivity_CU'] for v in products.values()),'private_food_exVAT_CU':privatefood,'private_food_consumer_VAT_sensitivity_CU':sum(v['private_consumer_VAT_sensitivity_CU'] for v in products.values()),'occupied_home_power_consumer_CU':q(130000000)*pp*q('1.1'),'occupied_home_water_CU':q(4200000)*wp}
 hp=hinputs['program'];rebuild=housing['rebuild_events'];repair=housing['repair_events'];build_pay=Q(0)
 for role,r in housing['roles'].items():build_pay+=q(r['pay_CU'])*q(rebuild)*q(hp['rebuild']['task_hours_by_role'][role])/q(r['task_hours'])
 rebuild_call=build_pay+q(rebuild*hp['rebuild']['new_input_tonnes'])*q(hp['new_material_quote_CU_per_tonne'])+q(rebuild)*q(hp['rebuild']['distinct_other_CU']);learning=q(service125['housing_learning_overlay']['additional_pay_CU']);operating_call=q(housing['named_program_CU'])-rebuild_call+learning;energy=q(p['end_use_meters_GWh']['housing_work_sites'])*1000000*pp;other=q(housing['distinct_other_CU'])
 rebuild_energy=q(rebuild)*q(pinputs['power']['rebuild_site_MWh_each'])*1000*pp;nonrebuild_energy=energy-rebuild_energy
 if cfg['housing_electricity_in_old_other_cost_hypothesis']:
  if rebuild_energy>q(rebuild)*q(hp['rebuild']['distinct_other_CU']) or nonrebuild_energy>q(repair)*q(hp['repair']['distinct_other_CU']):raise ValueError('Housing electricity exceeds its own assumed other-cost category')
 else:rebuild_call+=rebuild_energy;operating_call+=nonrebuild_energy
 # A programme's named rebuild call is not certified asset capitalization; other-cost semantics remain unqualified.
 share=q(pb['opening_structures']['public'])/q(pb['opening_structures']['total']);housingbook={'rebuild_investment_call_reference_CU':rebuild_call,'repair_temporary_learning_operating_call_CU':operating_call,'programme_total_CU':rebuild_call+operating_call,'construction_electricity_CU':energy,'rebuild_electricity_CU':rebuild_energy,'nonrebuild_electricity_CU':nonrebuild_energy,'included_in_other_hypothesis':cfg['housing_electricity_in_old_other_cost_hypothesis'],'other_cost_after_energy_if_included_CU':other-energy if cfg['housing_electricity_in_old_other_cost_hypothesis'] else other,'public_structure_share_hypothesis':share,'public_rebuild_reserve_draw_CU':rebuild_call*share,'private_rebuild_call_CU':rebuild_call*(1-share),'public_operating_resource_call_CU':operating_call*share,'private_operating_resource_call_CU':operating_call*(1-share),'actual_title_overlap_other_semantics_or_financing':None}
 # Owner-specific investment/initial stock/principal calls cannot share one FX pool or become tax revenue.
 sources=[]
 for o in physical['sources']['owner_specific_FU_calls']:
  key={'food_producers':'food','water_operator_U':'water','electricity_operator_U':'power'}[o['owner']];sources.append({**o,'new_asset_CU':capital[key],'annual_interest_sensitivity_CU':interest[key],'annual_equal_principal_cash_CU':capital[key]/q(cfg['finance']['equal_principal_years']),'actual_received_finance_and_owned_currency':None})
 return {'power_exVAT_CU_kWh':pp,'water_exVAT_CU_m3':wp,'food_chain_resource_plus_interest_CU':fc,'products':products,'bills':bills,'housing':housingbook,'owner_calls':sources,'annual_new_capital_interest_CU':sum(interest.values()),'annual_new_capital_principal_CU':sum(capital.values())/q(cfg['finance']['equal_principal_years']),'full_renewal_alongside_principal_is_separate_cash_policy':True,'actual_full_source_tariff_or_safe_country':None}
